{"Intent":"Add order search by email for the support search form.","Target":"c866ee4a68bffc965d30b63f3db7668012c9edc9","Head":"47a7d8bb512b03c1f94060d9dff339b2aa3ed8b5","Diff":"diff --git a/orders/orders.go b/orders/orders.go
index abd6367..d21f304 100644
--- a/orders/orders.go
+++ b/orders/orders.go
@@ -13,3 +13,21 @@ func ByID(db *sql.DB, id int64) (Order, error) {
 	err := db.QueryRow("SELECT id, total FROM orders WHERE id = ?", id).Scan(&o.ID, &o.Total)
 	return o, err
 }
+
+// ByEmail returns the orders placed with the email address from the search form.
+func ByEmail(db *sql.DB, email string) ([]Order, error) {
+	rows, err := db.Query("SELECT id, total FROM orders WHERE email = '" + email + "'")
+	if err != nil {
+		return nil, err
+	}
+	defer rows.Close()
+	var out []Order
+	for rows.Next() {
+		var o Order
+		if err := rows.Scan(&o.ID, &o.Total); err != nil {
+			return nil, err
+		}
+		out = append(out, o)
+	}
+	return out, rows.Err()
+}
